"""Copy the knowledge base into the static Space so both versions share it.

    python tools/build_static.py

chatbot/intents.json stays the single source of truth; this writes
hf_space/intents.js (a script tag, so index.html also works when opened
straight from disk, where browsers block fetch()).
"""

import json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
data = json.loads((ROOT / "chatbot" / "intents.json").read_text(encoding="utf-8"))
out = ROOT / "hf_space" / "intents.js"
out.write_text(
    "// GENERATED by tools/build_static.py from chatbot/intents.json - edit that file instead.\n"
    "window.TRADBOT_INTENTS = " + json.dumps(data, indent=1, ensure_ascii=False) + ";\n",
    encoding="utf-8",
)
print(f"wrote {out.relative_to(ROOT)} ({len(data['intents'])} intents)")
